window.HOEREN_TESTS[21] = {"id":"kleidung-und-mode","name":"Kleidung und Mode","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Kunden im Modegeschäft City, herzlich willkommen. Heute haben wir besondere Angebote: 30 Prozent auf alle Sommerkleider, 20 Prozent auf Jacken. Schuhe sind nicht im Sale, also keine 30 Prozent auf Schuhe. Aber wir haben eine Treuekarte: ab dem dritten Paar Schuhe sind 10 Prozent Rabatt. Ohne Treuekarte gibt es bei Schuhen keinen Rabatt. Schönen Einkauf und fragen Sie uns gern!","gender":"f","q":"Was bekommt man mit der Treuekarte bei Schuhen?","opts":["30 Prozent Rabatt.","Rabatt ab dem dritten Paar.","Keinen Rabatt."],"correct":1},{"transcript":"Hallo Anna, hier ist Mama. Du, deine Schwester braucht ein neues Kleid für die Hochzeit am Samstag. Sie hat kein passendes. Kannst du sie heute oder morgen zum Einkaufen begleiten? Du hast einen besseren Geschmack als sie. Bitte ruf zurück, ob du Zeit hast. Danke dir!","gender":"f","q":"Wofür braucht die Schwester ein Kleid?","opts":["Für eine Geburtstagsparty.","Für eine Hochzeit.","Für die Arbeit."],"correct":1},{"transcript":"Liebe Mütter und Väter, eine Mitteilung von der Schule. Wegen einer Sportveranstaltung am Donnerstag sollen alle Kinder Sportkleidung mitbringen — kein Sportzeug zum Wechseln, sondern direkt in der Schule getragen. Auch keine guten Sachen anziehen, weil wir draußen sind und es schmutzig wird. Vielen Dank an alle!","gender":"f","q":"Was sollen die Kinder am Donnerstag anziehen?","opts":["Sportkleidung von Anfang an.","Schöne Sachen.","Wintermäntel."],"correct":0},{"transcript":"Hi Maria, hier ist das Modegeschäft Stern. Das Kleid, das du letzte Woche bestellt hast — es ist endlich da. Aber leider in einer anderen Farbe als bestellt. Statt Rot ist es Blau gekommen. Bitte ruf zurück: möchtest du es trotzdem nehmen, umtauschen oder dein Geld zurück?","gender":"m","q":"Was ist das Problem?","opts":["Das Kleid ist nicht angekommen.","Falsche Größe.","Falsche Farbe gekommen."],"correct":2},{"transcript":"Achtung, liebe Kunden: Unser Geschäft schließt heute um 20 Uhr statt 22 Uhr, wegen Inventur. Die letzten 30 Minuten werden alle Kassen offen sein, aber bitte mit Ihrem Einkauf bis 19 Uhr 30 fertig sein, damit alles ruhig verläuft. Morgen sind wir wieder zu normalen Zeiten geöffnet. Vielen Dank für Ihr Verständnis!","gender":"f","q":"Bis wann sollen Kunden ihren Einkauf fertig machen?","opts":["Bis 19 Uhr 30.","Bis 20 Uhr.","Bis 22 Uhr."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer schenkt was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lisa","gender":"f","text":"Hallo Sara! Zum Geburtstag von Frau Berger brauchen wir passende Geschenke. Ich habe eine Liste."},{"speaker":"Sara","gender":"f","text":"Dann verteilen wir die Geschenke laut und klar. Ich will nichts doppelt kaufen."},{"speaker":"Lisa","gender":"f","text":"Ich schenke ein elegantes Tagebuch. Der Einband ist dunkelblau und ganz schlicht."},{"speaker":"Sara","gender":"f","text":"Ein Tagebuch kann sie abends füllen. Ich sah ein Kochbuch im Regal. Schenken wir das?"},{"speaker":"Lisa","gender":"f","text":"Ein Kochbuch schenken wir nicht. Sie kocht selten nach einem Rezept."},{"speaker":"Sara","gender":"f","text":"Dann schenke ich ihr ein schönes Foto-Album."},{"speaker":"Lisa","gender":"f","text":"Das Foto-Album füllen wir mit Bildern vom Fest. Tom bringt etwas zum Anstoßen."},{"speaker":"Sara","gender":"f","text":"Tom schenkt eine Flasche Wein. Der Rotwein kommt aus dem kleinen Laden an der Ecke."},{"speaker":"Lisa","gender":"f","text":"Eine Flasche reicht zum Anstoßen. Wollen wir einen Blumenstrauß dazu?"},{"speaker":"Sara","gender":"f","text":"Nein. Einen Blumenstrauß bringen wir nicht mit. Sie hat zu Hause schon viele Vasen."},{"speaker":"Lisa","gender":"f","text":"Lukas denkt schon an ihre nächste Reise."},{"speaker":"Sara","gender":"f","text":"Lukas schenkt eine Reisetasche. Sie ist leicht und hat vorne viele Fächer."},{"speaker":"Lisa","gender":"f","text":"Eine Reisetasche kann sie gut gebrauchen. Anna und Markus schenken zusammen."},{"speaker":"Sara","gender":"f","text":"Anna und Markus schenken Geld in einem Umschlag. Das wünscht sie sich selbst."},{"speaker":"Lisa","gender":"f","text":"Einverstanden. Ich schreibe die Geschenke auf eine Karte. Bis Samstag beim Fest."}],"options":[{"letter":"a","text":"ein Gutschein fürs Spa"},{"letter":"b","text":"Geld in einem Umschlag"},{"letter":"c","text":"ein Kochbuch"},{"letter":"d","text":"eine Flasche Wein"},{"letter":"e","text":"Blumenstrauß"},{"letter":"f","text":"ein elegantes Tagebuch"},{"letter":"g","text":"ein Foto-Album"},{"letter":"h","text":"eine Reisetasche"},{"letter":"i","text":"Geschirr für die Küche"}],"items":[{"person":"Lisa","correct":"f"},{"person":"Sara","correct":"g"},{"person":"Tom","correct":"d"},{"person":"Lukas","correct":"h"},{"person":"Anna und Markus","correct":"b"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Verkäuferin","gender":"f","text":"Guten Tag, welche Hose suchen Sie — Jeans oder etwas anderes?"},{"speaker":"Kunde","gender":"m","text":"Jeans, Größe 32 bitte. Nicht zu eng und nicht zu weit."},{"speaker":"Verkäuferin","gender":"f","text":"Slim Fit, Regular oder Bootcut? Alle drei haben wir in 32."},{"speaker":"Kunde","gender":"m","text":"Bootcut habe ich schon zu Hause. Slim Fit ist mir zu eng. Regular Fit bitte."},{"speaker":"Verkäuferin","gender":"f","text":"Gerne, hier Regular Fit in Größe 32. Die Kabine ist dort hinten."}],"q":"Welche Jeans nimmt der Kunde?","opts":["Slim Fit.","Bootcut.","Regular Fit."],"correct":2},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, ich möchte diese Bluse umtauschen, sie passt nicht. Was geht — Größe, Geld oder Gutschein?"},{"speaker":"Verkäuferin","gender":"f","text":"Möchten Sie eine andere Größe oder das Geld zurück? Einen Gutschein können wir auch geben."},{"speaker":"Kundin","gender":"f","text":"Eine andere Größe brauche ich nicht, Gutschein auch nicht. Eigentlich möchte ich nur Geld zurück."},{"speaker":"Verkäuferin","gender":"f","text":"Mit Bon? Geld zurück, kein Problem. Hier sind 29 Euro."},{"speaker":"Kundin","gender":"f","text":"Danke, das ist am einfachsten für mich."}],"q":"Was bekommt die Kundin?","opts":["Eine andere Größe.","Geld zurück.","Einen Gutschein."],"correct":1},{"lines":[{"speaker":"Mutter","gender":"f","text":"Du brauchst neue Schuhe für die Schule, oder? Sportschuhe, normale oder Stiefel?"},{"speaker":"Tochter","gender":"f","text":"Ja, meine alten sind kaputt. Stiefel brauche ich im Sommer nicht."},{"speaker":"Mutter","gender":"f","text":"Sportschuhe oder normale Schuhe für den Schultag?"},{"speaker":"Tochter","gender":"f","text":"Für den normalen Schultag sind normale besser. Sportschuhe habe ich noch, die alten gehen."},{"speaker":"Mutter","gender":"f","text":"Okay, normale Schuhe dann. Wir schauen in der nächsten Gasse."}],"q":"Welche Schuhe kauft sie?","opts":["Normale Schuhe.","Sportschuhe.","Stiefel."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Welche Krawatte passt zum blauen Anzug — rot, gelb oder noch eine blaue?"},{"speaker":"Frau","gender":"f","text":"Eine rote ist klassisch. Oder gelb für etwas Modisches. Eine blaue Krawatte zum blauen Anzug ist langweilig."},{"speaker":"Mann","gender":"m","text":"Gelb ist mir zu auffällig, blau auch nicht. Rot dann."},{"speaker":"Frau","gender":"f","text":"Gute Wahl. Rot mit Blau sieht immer gut aus, nicht gelb."},{"speaker":"Mann","gender":"m","text":"Super, ich nehme die rote. Danke für den Tipp."}],"q":"Welche Krawatte wählt der Mann?","opts":["Eine blaue.","Eine gelbe.","Eine rote."],"correct":2},{"lines":[{"speaker":"Mitarbeiterin","gender":"f","text":"Guten Tag, suchen Sie ein Geschenk? Schmuck vielleicht?"},{"speaker":"Kunde","gender":"m","text":"Ja, für meine Frau. Ohrringe, Halsketten oder Armbänder — was empfehlen Sie?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Ohrringe, Halskette oder Armband, alles schön. Was trägt sie gern?"},{"speaker":"Kunde","gender":"m","text":"Sie trägt nur Ohrringe und Armbänder, keine Halsketten. Heute schaue ich Armbänder an, Ohrringe hat sie schon viele."},{"speaker":"Mitarbeiterin","gender":"f","text":"Dann zeige ich Ihnen unsere Armbänder. Hier, diese sind neu."}],"q":"Welchen Schmuck schaut der Mann an?","opts":["Ohrringe.","Armbänder.","Halsketten."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Klein, einer Mode-Designerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Klein, Sie sind Mode-Designerin seit 10 Jahren. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Klein","gender":"f","text":"Schon als kleines Mädchen habe ich Kleider für meine Puppen geschneidert. Mit 17 habe ich ein Praktikum in Paris gemacht — das war eine andere Welt. Danach Modedesign-Studium in Berlin. Ich hatte das Glück, dass meine Eltern mich finanziell unterstützen konnten."},{"speaker":"Reporter","gender":"m","text":"Welche Mode designen Sie?"},{"speaker":"Klein","gender":"f","text":"Vor allem Frauen-Kleidung, etwas elegant aber tragbar. Keine Haute-Couture, das ist nicht mein Stil. Eher Sachen, die jede Frau im Alltag tragen kann — gute Qualität, einfache Schnitte."},{"speaker":"Reporter","gender":"m","text":"Wie sind Ihre Arbeitstage?"},{"speaker":"Klein","gender":"f","text":"Sehr unterschiedlich. Manchmal sitze ich den ganzen Tag und zeichne. Manchmal bin ich im Atelier mit den Schneidern. Manchmal Stoff-Suche in verschiedenen Geschäften. Selten am Schreibtisch — meine Arbeit ist sehr praktisch."},{"speaker":"Reporter","gender":"m","text":"Was ist die Mode-Idee, die Sie am stolzesten macht?"},{"speaker":"Klein","gender":"f","text":"Meine Sommer-Kollektion vor 3 Jahren. Sie wurde in einer großen Modezeitschrift gezeigt, und meine Karriere ging ab da steil bergauf. Vor dieser Zeit war ich relativ unbekannt."},{"speaker":"Reporter","gender":"m","text":"Tragen Sie selbst nur Ihre eigenen Designs?"},{"speaker":"Klein","gender":"f","text":"Nein, überraschend nicht! Privat trage ich meistens Jeans und T-Shirts — sehr einfache Sachen. Meine Designs trage ich auf Geschäftsterminen und Veranstaltungen. Privat ist mir Komfort wichtiger."}],"items":[{"q":"Frau Klein hat ein Praktikum in Mailand gemacht.","correct":"nein"},{"q":"Sie designt Haute-Couture-Mode.","correct":"nein"},{"q":"Ihre Sommer-Kollektion vor 3 Jahren war ein großer Erfolg.","correct":"ja"},{"q":"Privat trägt sie meistens Jeans und T-Shirts.","correct":"ja"},{"q":"Sie sitzt den ganzen Tag am Schreibtisch.","correct":"nein"}]}]};
